function GetMapInitData(worldSize)
	return { Width = MAP_W, Height = MAP_H, WrapX = false }
end

local function TI(name) local t = GameInfo.Terrains[name]; if t then return t.Index end; return nil end
local function FI(name) local f = GameInfo.Features[name]; if f then return f.Index end; return nil end

function GenerateMap()
	print("Generating Warring States China map V3.23 (2026-10-09)")
	g_iW, g_iH = Map.GetGridSize()
	local W, H = g_iW, g_iH
	pcall(function() g_iFlags = TerrainBuilder.GetFractalFlags() end)

	local TERR = {
		["~"] = TI("TERRAIN_OCEAN"),          ["c"] = TI("TERRAIN_COAST"),
		["g"] = TI("TERRAIN_GRASS"),          ["G"] = TI("TERRAIN_GRASS_HILLS"),
		["p"] = TI("TERRAIN_PLAINS"),         ["P"] = TI("TERRAIN_PLAINS_HILLS"),
		["d"] = TI("TERRAIN_DESERT"),         ["D"] = TI("TERRAIN_DESERT_HILLS"),
		["M"] = TI("TERRAIN_PLAINS_MOUNTAIN"),["S"] = TI("TERRAIN_SNOW_MOUNTAIN"),
	}

	-- 1. terrain
	for y = 0, H - 1 do
		local row = TERRAIN_ROWS[MAP_H - y]
		for x = 0, W - 1 do
			local t = TERR["~"]
			if row and x < MAP_W then t = TERR[row:sub(x + 1, x + 1)] or TERR["~"] end
			local plot = Map.GetPlot(x, y)
			if plot and t ~= nil then pcall(TerrainBuilder.SetTerrainType, plot, t) end
		end
	end
	AreaBuilder.Recalculate()
	pcall(function() TerrainBuilder.AnalyzeChokepoints() end)
	local okc, errc = pcall(function() TerrainBuilder.StampContinents() end)
	if not okc then print('StampContinents failed: ' .. tostring(errc)) end

	-- 2. gameplay rivers (for housing / defence only; the big rivers are coast tiles)
	local ok, err = pcall(function() AddRivers() end)
	if not ok then print("AddRivers failed: " .. tostring(err)) end

	-- 2b. the Yellow River through Hangu and Luoyang as native river edges (keeps the land tiles and the corridor)
	pcall(function()
		local fNE, fSE = 1, 2
		pcall(function()
			fNE = FlowDirectionTypes.FLOWDIRECTION_NORTHEAST
			fSE = FlowDirectionTypes.FLOWDIRECTION_SOUTHEAST
		end)
		for _, c in ipairs(YELLOW_EDGE_CELLS) do
			local plot = Map.GetPlot(c.x, c.y)
			if plot ~= nil then
				TerrainBuilder.SetNEOfRiver(plot, true, fSE)
				TerrainBuilder.SetNWOfRiver(plot, true, fNE)
			end
		end
	end)

	-- 2c. fresh water: coast-tile rivers give none, so add short native river edges beside them
	pcall(function()
		local f = { se = 2, s = 3, sw = 4 }
		pcall(function()
			f.se = FlowDirectionTypes.FLOWDIRECTION_SOUTHEAST
			f.s = FlowDirectionTypes.FLOWDIRECTION_SOUTH
			f.sw = FlowDirectionTypes.FLOWDIRECTION_SOUTHWEST
		end)
		local made = 0
		for _, r in ipairs(RIVER_PAIRS) do
			local p = Map.GetPlot(r[1], r[2])
			local q = Map.GetPlot(r[3], r[4])
			if p ~= nil and q ~= nil then
				for dir = 0, 5 do
					local adj = Map.GetAdjacentPlot(r[1], r[2], dir)
					if adj ~= nil and adj:GetX() == r[3] and adj:GetY() == r[4] then
						if dir == 0 then TerrainBuilder.SetNEOfRiver(q, true, f.se)
						elseif dir == 1 then TerrainBuilder.SetWOfRiver(p, true, f.s)
						elseif dir == 2 then TerrainBuilder.SetNWOfRiver(p, true, f.sw)
						elseif dir == 3 then TerrainBuilder.SetNEOfRiver(p, true, f.se)
						elseif dir == 4 then TerrainBuilder.SetWOfRiver(q, true, f.s)
						elseif dir == 5 then TerrainBuilder.SetNWOfRiver(q, true, f.sw) end
						made = made + 1
						break
					end
				end
			end
		end
		print("Fresh-water river edges placed: " .. tostring(made))
	end)

	-- 3. features
	local FEAT = { f = FI("FEATURE_FOREST"), j = FI("FEATURE_JUNGLE"), m = FI("FEATURE_MARSH") }
	for y = 0, H - 1 do
		local row = FEATURE_ROWS[MAP_H - y]
		if row then
			for x = 0, W - 1 do
				local ch = row:sub(x + 1, x + 1)
				local idx = FEAT[ch]
				if idx ~= nil then
					local plot = Map.GetPlot(x, y)
					local good, _ = pcall(function()
						if TerrainBuilder.CanHaveFeature(plot, idx) then
							TerrainBuilder.SetFeatureType(plot, idx)
						end
					end)
				end
			end
		end
	end
	AreaBuilder.Recalculate()
	pcall(function() TerrainBuilder.StampContinents() end)

	-- 3a. cliffs along the Nanjing stretch of the Yangtze: land units cannot embark/disembark except from cities
	pcall(function()
		for _, c in ipairs(CLIFF_CELLS) do
			local plot = Map.GetPlot(c.x, c.y)
			if plot ~= nil then
				for dir = 0, 5 do
					local adj = Map.GetAdjacentPlot(c.x, c.y, dir)
					if adj ~= nil and adj:IsWater() then
						if dir == 0 then TerrainBuilder.SetNEOfCliff(adj, true)
						elseif dir == 1 then TerrainBuilder.SetWOfCliff(plot, true)
						elseif dir == 2 then TerrainBuilder.SetNWOfCliff(plot, true)
						elseif dir == 3 then TerrainBuilder.SetNEOfCliff(plot, true)
						elseif dir == 4 then TerrainBuilder.SetWOfCliff(adj, true)
						elseif dir == 5 then TerrainBuilder.SetNWOfCliff(adj, true) end
					end
				end
			end
		end
	end)

	-- 3b. natural wonders (the game picks suitable spots), then keep passes and city sites clear of them
	pcall(function()
		-- about twice the Huge default (7): the map is mostly land
		local n = 15
		NaturalWonderGenerator.Create({ numberToPlace = n })
	end)
	pcall(function()
		for _, c in ipairs(KEEP_CELLS) do
			local p = Map.GetPlot(c.x, c.y)
			if p ~= nil and p:IsNaturalWonder() then
				TerrainBuilder.SetFeatureType(p, -1)
				local row = TERRAIN_ROWS[MAP_H - c.y]
				local t = row and TERR[row:sub(c.x + 1, c.x + 1)]
				if t ~= nil then TerrainBuilder.SetTerrainType(p, t) end
			end
		end
		local nw = 0
		for k = 0, W * H - 1 do
			local p = Map.GetPlotByIndex(k)
			if p ~= nil and p:IsNaturalWonder() then nw = nw + 1 end
		end
		print("Natural wonders: " .. tostring(nw) .. " plots after clearing passes and city sites")
	end)

	-- 4. resources
	local okr, errr = pcall(function()
		local args = { resources = MapConfiguration.GetValue("resources"), START_CONFIG = MapConfiguration.GetValue("start") }
		ResourceGenerator.Create(args)
	end)
	if not okr then print("ResourceGenerator failed: " .. tostring(errr)) end

	-- 4b. historical city-site resources + regional scatter (placed on top of the default resources)
	-- step > 1 thins the list: every Nth spot of a run of the same resource, every Nth lone luxury
	local function PlaceList(list, useFallback, step)
		step = step or 1
		local runPos, lone = 0, 0
		for i, r in ipairs(list) do
			local prev, nxt = list[i - 1], list[i + 1]
			if prev ~= nil and prev.res == r.res then runPos = runPos + 1 else runPos = 0 end
			local use = runPos % step == 0
			local info = GameInfo.Resources["RESOURCE_" .. r.res]
			local luxury = info ~= nil and info.ResourceClassType == "RESOURCECLASS_LUXURY"
			if use and luxury and runPos == 0 and (nxt == nil or nxt.res ~= r.res) then
				use = lone % step == 0
				lone = lone + 1
			end
			local plot = use and Map.GetPlot(r.x, r.y) or nil
			if plot then
				local names = { r.res }
				local alts = RES_ALTS[r.res]
				if alts then for _, a in ipairs(alts) do names[#names + 1] = a end end
				if useFallback then for _, a in ipairs(RES_FALLBACK) do names[#names + 1] = a end end
				local placed = false
				for _, name in ipairs(names) do
					if not placed then
						local info = GameInfo.Resources["RESOURCE_" .. name]
						if info ~= nil then
							pcall(function()
								local cur = plot:GetResourceType()
								local had = (cur ~= nil and cur >= 0)
								local can = ResourceBuilder.CanHaveResource(plot, info.Index)
								if not can and had then
									ResourceBuilder.SetResourceType(plot, -1)
									can = ResourceBuilder.CanHaveResource(plot, info.Index)
									if not can then ResourceBuilder.SetResourceType(plot, cur, 1) end
								end
								if can then
									ResourceBuilder.SetResourceType(plot, info.Index, 1)
									placed = true
								end
							end)
						end
					end
				end
			end
		end
	end
	if USE_SITE_RESOURCES then
		pcall(function() PlaceList(SITE_RESOURCES, false) end)
		pcall(function() PlaceList(GUAR_RESOURCES, false, GUAR_RESOURCES_STEP) end)
		if USE_SCATTER_RESOURCES then pcall(function() PlaceList(SCATTER_RESOURCES, true) end) end
	end

	-- 4c. Ley Lines (Secret Societies mode / Golden Dawn): custom maps do not get them automatically
	pcall(function()
		local leyIdx = nil
		for row in GameInfo.Resources() do
			if row.ResourceType ~= nil and string.find(row.ResourceType, "LEY") then leyIdx = row.Index end
		end
		if leyIdx == nil then print("Ley line resource not found (Secret Societies not available)"); return end
		local placed = {}
		for _, c in ipairs(LEY_CANDIDATES) do
			local plot = Map.GetPlot(c.x, c.y)
			if plot ~= nil then
				local ok = true
				for _, p in ipairs(placed) do
					if Map.GetPlotDistance(c.x, c.y, p.x, p.y) < LEY_MIN_DIST then ok = false; break end
				end
				if ok then
					pcall(function()
						local cur = plot:GetResourceType()
						if cur == nil or cur < 0 then
							local can = ResourceBuilder.CanHaveResource(plot, leyIdx)
							if can then
								ResourceBuilder.SetResourceType(plot, leyIdx, 1)
								placed[#placed + 1] = { x = c.x, y = c.y }
							end
						end
					end)
				end
			end
		end
		print("Ley lines placed: " .. tostring(#placed))
	end)

	-- 5. default start positions (fallback + minor civs), then override majors with fixed ones
	local oks, errs = pcall(function()
		local args = {
			MIN_MAJOR_CIV_FERTILITY = 150, MIN_MINOR_CIV_FERTILITY = 50, MIN_BARBARIAN_FERTILITY = 1,
			START_MIN_Y = 15, START_MAX_Y = 15,
			START_CONFIG = MapConfiguration.GetValue("start"), LAND = true,
		}
		AssignStartingPlots.Create(args)
	end)
	if not oks then print("AssignStartingPlots failed: " .. tostring(errs)) end

	local okf, errf = pcall(function()
		if not USE_FIXED_STARTS then return end
		local majors = PlayerManager.GetAliveMajorIDs()
		print("FixedStarts: major players = " .. tostring(#majors))
		-- 0. with fewer players than positions, only use one of the most spread-out groups of positions
		local allowed = {}
		local sets = SPREAD_SETS[#majors]
		if sets ~= nil and #sets > 0 then
			local pick = sets[TerrainBuilder.GetRandomNumber(#sets, "Pick spread set") + 1]
			local names = ""
			for _, nm in ipairs(pick) do allowed[nm] = true; names = names .. nm .. " " end
			print("FixedStarts: spread set for " .. tostring(#majors) .. " players = " .. names)
		end
		-- 1. bound leaders take their preferred start positions
		local assigned = {}
		local usedSlot = {}
		for _, pid in ipairs(majors) do
			local lname = ""
			pcall(function() lname = PlayerConfigurations[pid]:GetLeaderTypeName() or "" end)
			print("FixedStarts: player " .. tostring(pid) .. " leader = " .. tostring(lname))
			for _, bnd in ipairs(LEADER_BIND) do
				if assigned[pid] == nil and string.find(lname, bnd.match, 1, true) then
					for _, slotName in ipairs(bnd.slots) do
						if assigned[pid] == nil then
							for si, sp in ipairs(START_POSITIONS) do
								if sp.name == slotName and not usedSlot[si] then
									assigned[pid] = si; usedSlot[si] = true
									print("FixedStarts: leader binding " .. bnd.match .. " -> " .. slotName)
									break
								end
							end
						end
					end
				end
			end
		end
		-- 1b. the human player takes one of the most isolated positions of the chosen group (distance capped at 24 tiles, random among equals)
		if HUMAN_SAFEST then
			for _, pid in ipairs(majors) do
				if assigned[pid] == nil then
					local isHuman = false
					pcall(function() isHuman = Players[pid]:IsHuman() end)
					if isHuman then
						local scores = {}
						local bestD = -1
						for si, sp in ipairs(START_POSITIONS) do
							if not usedSlot[si] and (next(allowed) == nil or allowed[sp.name]) then
								local nearest = 999
								for sj, sq in ipairs(START_POSITIONS) do
									if sj ~= si and (next(allowed) == nil or allowed[sq.name]) then
										local dd = START_DIST[sp.name][sq.name]
										if dd ~= nil and dd < nearest then nearest = dd end
									end
								end
								if nearest > 24 then nearest = 24 end
								scores[si] = nearest
								if nearest > bestD then bestD = nearest end
							end
						end
						local pool = {}
						for si, v in pairs(scores) do if v == bestD then pool[#pool + 1] = si end end
						table.sort(pool)
						if #pool > 0 then
							local si = pool[TerrainBuilder.GetRandomNumber(#pool, "Safe start") + 1]
							assigned[pid] = si; usedSlot[si] = true
							print("FixedStarts: human player " .. tostring(pid) .. " -> safe start " .. START_POSITIONS[si].name .. " (nearest rival " .. tostring(bestD) .. "+ tiles)")
						end
					end
				end
			end
		end
		-- 2. everybody else: shuffle the remaining positions
		local slots = {}
		for si = 1, #START_POSITIONS do
			if not usedSlot[si] and (next(allowed) == nil or allowed[START_POSITIONS[si].name]) then slots[#slots + 1] = si end
		end
		for i = #slots, 2, -1 do
			local j = TerrainBuilder.GetRandomNumber(i, "Shuffle starts") + 1
			slots[i], slots[j] = slots[j], slots[i]
		end
		local nextSlot = 1
		for _, pid in ipairs(majors) do
			if assigned[pid] == nil and slots[nextSlot] ~= nil then assigned[pid] = slots[nextSlot]; nextSlot = nextSlot + 1 end
		end
		local taken = {}
		for _, pid in ipairs(majors) do
			local s = assigned[pid]
			if s then
				local sp = START_POSITIONS[s]
				local plot = Map.GetPlot(sp.x, sp.y)
				Players[pid]:SetStartingPlot(plot)
				print("FixedStarts: player " .. tostring(pid) .. " -> " .. sp.name .. " (" .. sp.x .. "," .. sp.y .. ")")
				taken[#taken + 1] = sp
			end
		end
		-- 3. players left without a position (more players than positions): keep the engine choice unless too close to a fixed start
		for _, pid in ipairs(majors) do
			if assigned[pid] == nil then
				local cur = Players[pid]:GetStartingPlot()
				local bad = (cur == nil)
				if cur then
					for _, sp in ipairs(taken) do
						if Map.GetPlotDistance(cur:GetX(), cur:GetY(), sp.x, sp.y) < 5 then bad = true end
					end
				end
				if bad then
					for k = 0, W * H - 1, 37 do
						local p = Map.GetPlotByIndex(k)
						if p and not p:IsWater() and not p:IsMountain() then
							local far = true
							for _, sp in ipairs(taken) do
								if Map.GetPlotDistance(p:GetX(), p:GetY(), sp.x, sp.y) < 6 then far = false end
							end
							if far then Players[pid]:SetStartingPlot(p); taken[#taken + 1] = { x = p:GetX(), y = p:GetY() }; break end
						end
					end
				end
			end
		end
		-- 4. city-states were placed by the engine around its own major starts, before the majors moved to the fixed
		--    positions: move any that ended up too close to a major to the nearest free spot (same spacing as the engine)
		local MIN_TO_MAJOR, MIN_TO_MINOR = 7, 6
		local majorPlots = {}
		for _, pid in ipairs(majors) do
			local p = Players[pid]:GetStartingPlot()
			if p then majorPlots[#majorPlots + 1] = p end
		end
		local minors = PlayerManager.GetAliveMinorIDs()
		local minorPlots = {}
		for _, pid in ipairs(minors) do minorPlots[pid] = Players[pid]:GetStartingPlot() end
		local function FarFrom(x, y, list, minDist, skip)
			for key, q in pairs(list) do
				if key ~= skip and q ~= nil and Map.GetPlotDistance(x, y, q:GetX(), q:GetY()) < minDist then return false end
			end
			return true
		end
		local keep = {}
		for _, c in ipairs(KEEP_CELLS) do keep[c.y * W + c.x] = true end
		for _, pid in ipairs(minors) do
			local cur = minorPlots[pid]
			if cur ~= nil and not FarFrom(cur:GetX(), cur:GetY(), majorPlots, MIN_TO_MAJOR) then
				local best, bestD = nil, 999
				for k = 0, W * H - 1 do
					local p = Map.GetPlotByIndex(k)
					if p and not p:IsWater() and not p:IsImpassable() and not p:IsNaturalWonder() and not keep[k] then
						local d = Map.GetPlotDistance(p:GetX(), p:GetY(), cur:GetX(), cur:GetY())
						if d < bestD and FarFrom(p:GetX(), p:GetY(), majorPlots, MIN_TO_MAJOR)
							and FarFrom(p:GetX(), p:GetY(), minorPlots, MIN_TO_MINOR, pid) then
							best, bestD = p, d
						end
					end
				end
				if best then
					Players[pid]:SetStartingPlot(best)
					minorPlots[pid] = best
					print("FixedStarts: city-state " .. tostring(pid) .. " moved (" .. cur:GetX() .. "," .. cur:GetY() .. ") -> (" .. best:GetX() .. "," .. best:GetY() .. ")")
				else
					print("FixedStarts: city-state " .. tostring(pid) .. " too close to a major, no free spot found")
				end
			end
		end
	end)
	if not okf then print("FixedStarts error: " .. tostring(errf)) end

	-- 6. tribal villages ("mushrooms"): randomised every game, kept away from every start position
	pcall(function()
		local hutInfo = GameInfo.Improvements["IMPROVEMENT_GOODY_HUT"]
		local hutIdx = nil
		if hutInfo ~= nil then hutIdx = hutInfo.Index end
		-- respect the "No Tribal Villages" game option (AddGoodies already checks it, our top-up must too)
		if GameConfiguration.GetValue("GAME_NO_GOODY_HUTS") == true then print("Goodies: game set to no tribal villages"); return end
		local placed = {}
		local function FindHuts()
			placed = {}
			if hutIdx == nil then return 0 end
			for k = 0, W * H - 1 do
				local p = Map.GetPlotByIndex(k)
				if p ~= nil and p:GetImprovementType() == hutIdx then placed[#placed + 1] = { x = p:GetX(), y = p:GetY() } end
			end
			return #placed
		end
		local okg, errg = pcall(function() AddGoodies(g_iW, g_iH) end)
		print("Goodies: AddGoodies ok=" .. tostring(okg) .. " err=" .. tostring(errg))
		local have = FindHuts()
		print("Goodies: tribal villages after AddGoodies = " .. tostring(have))
		if hutIdx == nil then print("Goodies: IMPROVEMENT_GOODY_HUT not found"); return end
		-- our own placement: about one village per 35 land tiles (twice the old density, the map is mostly land),
		-- at least 7 tiles from every fixed start and 4 from every city-state, 3 tiles from any other village
		local keep = {}
		for _, c in ipairs(KEEP_CELLS) do keep[c.y * W + c.x] = true end
		-- city-states too (the engine's AddGoodies keeps villages off every start, ours must as well)
		local minorStarts = {}
		for _, pid in ipairs(PlayerManager.GetAliveMinorIDs()) do
			local sp = Players[pid]:GetStartingPlot()
			if sp then minorStarts[#minorStarts + 1] = sp end
		end
		local cand = {}
		local landCount = 0
		for k = 0, W * H - 1 do
			local p = Map.GetPlotByIndex(k)
			if p ~= nil and not p:IsWater() and not p:IsMountain() then
				landCount = landCount + 1
				local ok = (p:GetImprovementType() < 0) and (p:GetResourceType() < 0) and (not p:IsNaturalWonder()) and (not keep[k])
				if ok then
					for _, sp in ipairs(START_POSITIONS) do
						if Map.GetPlotDistance(p:GetX(), p:GetY(), sp.x, sp.y) < 7 then ok = false; break end
					end
				end
				if ok then
					for _, sp in ipairs(minorStarts) do
						if Map.GetPlotDistance(p:GetX(), p:GetY(), sp:GetX(), sp:GetY()) < 4 then ok = false; break end
					end
				end
				if ok then cand[#cand + 1] = k end
			end
		end
		local target = math.floor(landCount / 35)
		if have >= target then print("Goodies: enough villages already"); return end
		for i = #cand, 2, -1 do
			local j = TerrainBuilder.GetRandomNumber(i, "Hut shuffle") + 1
			cand[i], cand[j] = cand[j], cand[i]
		end
		local made = 0
		for _, k in ipairs(cand) do
			if have + made >= target then break end
			local p = Map.GetPlotByIndex(k)
			local far = true
			for _, q in ipairs(placed) do
				if Map.GetPlotDistance(p:GetX(), p:GetY(), q.x, q.y) < 3 then far = false; break end
			end
			if far then
				local okp = pcall(function() ImprovementBuilder.SetImprovementType(p, hutIdx, -1) end)
				if okp then placed[#placed + 1] = { x = p:GetX(), y = p:GetY() }; made = made + 1 end
			end
		end
		print("Goodies: added " .. tostring(made) .. " tribal villages (target " .. tostring(target) .. ")")
	end)
	print("Warring States map done")
end
